head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. group_init_WPF-862_(WSQ-2205).xml 실행하고 2번째 콤보박스에 checkcombobox를 클릭하여 값을 선택한다.(하나, 둘, 셋)- Run group_init_WPF-862_ (WSQ-2205) .xml and click the checkcombobox in the second combo box to select the value (one, two, three).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkcombobox1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_2_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 1. checkcombobox 값이 선택된다.- The checkcombobox value is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_2_checkbox').checked", "true");
    //Test step 2. init버튼을 클릭한다.- Click the init button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify 2. checkcombobox 값이 초기화된다.(기존에는 초기화되지 않음)- The checkcombobox value is initialized (it is not initialized in the past)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_1_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_2_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    input1.setValue("input..");
    checkcombobox1.setValue(222);
    selectbox1.setValue(33);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 19-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
